	@Test
	public void testInterruptedCountReleasesPartialLeasesAcrossStoreDictionaries(@TempDir File root) throws Exception {
		File targetDirectory = new File(root, "target");
		File foreignDirectory = new File(root, "foreign");
		if (!targetDirectory.isDirectory() && !targetDirectory.mkdirs()) {
			throw new IOException("Could not create target reader-exhaustion store directory: " + targetDirectory);
		}
		if (!foreignDirectory.isDirectory() && !foreignDirectory.mkdirs()) {
			throw new IOException("Could not create foreign reader-exhaustion store directory: " + foreignDirectory);
		}
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try (LmdbSailStore target = new LmdbSailStore(targetDirectory, new StoreProperties(targetDirectory), config);
				LmdbSailStore foreign = new LmdbSailStore(foreignDirectory, new StoreProperties(foreignDirectory),
						config);
				SailDataset dataset = target.getExplicitSailSource().dataset(IsolationLevels.NONE)) {
			ValueStore foreignValues = (ValueStore) foreign.getValueFactory();
			IRI datatype = F.createIRI("urn:count-reader-exhaustion:datatype");
			Literal persisted = F.createLiteral("foreign dictionary lease", datatype);
			long persistedId = foreignValues.getId(persisted, true);
			foreignValues.commit();
			foreignValues.clearCaches();
			LmdbValue lazyObject = foreignValues.getLazyValue(persistedId);
			assertFalse(lazyObject.isInitialized());

			TxnManager foreignManager = foreignValues.getTxnManager();
			List<TxnManager.Txn> ordinaryReaders = new ArrayList<>();
			TxnManager.Txn reservedReader = null;
			StatementCountScope scope = new StatementCountScope(null, null, lazyObject, new Resource[0]);
			CountDownLatch partialLeaseReleased = new CountDownLatch(1);
			AtomicReference<Thread> freezeThread = new AtomicReference<>();
			try {
				for (int i = 0; i < TxnManager.POOL_SIZE - 1; i++) {
					ordinaryReaders.add(foreignManager.createReadTxn());
				}
				reservedReader = foreignManager.tryCreateReadTxnForCount(true);
				assertNotNull(reservedReader, "The fixture must consume the actual reserved native reader slot");

				StatementCountSource countSource = dataset.prepareStatementCount(scope);
				scope.register(new Object(), new StatementCountScope.CountResource() {
					@Override
					public long order() {
						return Long.MIN_VALUE;
					}
				});
				scope.register(new Object(), new StatementCountScope.CountResource() {
					@Override
					public long order() {
						return Long.MIN_VALUE + 1;
					}

					@Override
					public void releaseLease() {
						partialLeaseReleased.countDown();
					}
				});
				Future<Boolean> freeze = executor.submit(() -> {
					freezeThread.set(Thread.currentThread());
					return scope.freeze();
				});
				assertTrue("The scope must release acquired leases before waiting on the exhausted dictionary",
						partialLeaseReleased.await(5, TimeUnit.SECONDS));
				freezeThread.get().interrupt();
				ExecutionException failure = assertThrows(ExecutionException.class,
						() -> freeze.get(5, TimeUnit.SECONDS));
				assertTrue("The bounded count acquisition must surface interruption",
						failure.getCause() instanceof SailException);
				assertFalse("A failed count must leave the lazy foreign value uninitialized",
						lazyObject.isInitialized());
			} finally {
				try {
					scope.close();
				} finally {
					if (reservedReader != null) {
						reservedReader.close();
					}
					ordinaryReaders.forEach(TxnManager.Txn::close);
				}
			}

			assertAllCountReaderSlotsAvailable(((ValueStore) target.getValueFactory()).getTxnManager());
			assertAllCountReaderSlotsAvailable(foreignManager);
			assertFalse("Count preflight and failed admission must preserve lazy foreign values",
					lazyObject.isInitialized());
		} finally {
			executor.shutdownNow();
		}
	}

	private static void assertAllCountReaderSlotsAvailable(TxnManager manager) throws IOException {
		List<TxnManager.Txn> readers = new ArrayList<>(TxnManager.POOL_SIZE);
		try {
			for (int i = 0; i < TxnManager.POOL_SIZE - 1; i++) {
				TxnManager.Txn reader = manager.tryCreateReadTxnForCount(false);
				assertNotNull(reader, "Every ordinary count reader slot must be returned after failed admission");
				readers.add(reader);
			}
			assertNull(manager.tryCreateReadTxnForCount(false),
					"Ordinary count admission must stop at the reserved reader boundary");
			TxnManager.Txn priority = manager.tryCreateReadTxnForCount(true);
			assertNotNull(priority, "The reserved reader must remain available after cleanup");
			readers.add(priority);
			assertNull(manager.tryCreateReadTxnForCount(true),
					"The fully occupied native reader table must reject another count lease");
		} finally {
			readers.forEach(TxnManager.Txn::close);
		}
	}

	@Test
	public void testFrozenNativeCountKeepsBorrowedRootAcrossConcurrentCommitAndFilters(@TempDir File root)
			throws Exception {
		LmdbSailStore backingStore = new LmdbSailStore(root, new StoreProperties(root),
				new LmdbStoreConfig("spoc,posc"));
		ExecutorService executor = Executors.newSingleThreadExecutor();
		CountDownLatch writerAttempting = new CountDownLatch(1);
		Resource subject = F.createIRI("urn:frozen-count-root:subject");
		IRI predicate = F.createIRI("urn:frozen-count-root:predicate");
		Statement first = F.createStatement(subject, predicate, F.createLiteral("first"));
		Statement second = F.createStatement(subject, predicate, F.createLiteral("second"));
		Statement added = F.createStatement(subject, predicate, F.createLiteral("added-after-root-capture"));
		SailSource source = backingStore.getExplicitSailSource();
		try {
			try (SailSink sink = source.sink(IsolationLevels.NONE)) {
				sink.approve(first.getSubject(), first.getPredicate(), first.getObject(), first.getContext());
				sink.approve(second.getSubject(), second.getPredicate(), second.getObject(), second.getContext());
				sink.flush();
			}

			try (SailDataset rootDataset = source.dataset(IsolationLevels.NONE)) {
				Future<?> writer;
				try (StatementCountScope scope = new StatementCountScope(null, null, null, new Resource[0]);
						MockedConstruction<LmdbRecordIterator> recordIterators = mockConstruction(
								LmdbRecordIterator.class,
								(mock, context) -> doThrow(
										new AssertionError("Frozen native count must not scan raw records"))
										.when(mock)
										.next());
						MockedConstruction<LmdbStatementIterator> statementIterators = mockConstruction(
								LmdbStatementIterator.class,
								(mock, context) -> doThrow(
										new AssertionError("Frozen native count must not scan statements"))
										.when(mock)
										.next())) {
					StatementCountSource nativeSource = rootDataset.prepareStatementCount(scope);
					StatementCountSource heldSource = StatementCountSources.fromStatements(
							new Statement[] { first, second, added }, scope);
					assertTrue(scope.freeze());
					writer = executor.submit(() -> {
						writerAttempting.countDown();
						try (SailSink sink = source.sink(IsolationLevels.NONE)) {
							sink.deprecate(second);
							sink.approve(added.getSubject(), added.getPredicate(), added.getObject(),
									added.getContext());
							sink.flush();
						}
					});
					assertTrue("The writer must start while the captured count scope is frozen",
							writerAttempting.await(10, TimeUnit.SECONDS));
					assertEquals("The captured root transaction must retain its original total", 2,
							nativeSource.count(null, null, null, new Resource[0], null, scope));
					assertEquals("Native correction membership must use the same borrowed root", 2,
							nativeSource.count(null, null, null, new Resource[0],
									StatementCountSources.contains(heldSource), scope));
					assertEquals("The removed row must remain visible through the captured root", 1,
							nativeSource.count(subject, predicate, second.getObject(), new Resource[0],
									StatementCountSources.contains(heldSource), scope));
					assertEquals("The newly committed row must remain invisible through the captured root", 0,
							nativeSource.count(subject, predicate, added.getObject(), new Resource[0],
									StatementCountSources.contains(heldSource), scope));
					assertEquals("Repeated corrections must retain the original root transaction", 1,
							nativeSource.count(subject, predicate, second.getObject(), new Resource[0], null, scope));
					assertTrue("Frozen native counts must not construct raw record iterators",
							recordIterators.constructed().isEmpty());
					assertTrue("Frozen native counts must not construct statement iterators",
							statementIterators.constructed().isEmpty());
				}
				writer.get(10, TimeUnit.SECONDS);
				assertEquals("After the frozen scope closes, the tracked dataset may renew to the committed state", 0,
						rootDataset.getStatementCount(subject, predicate, second.getObject()));
				assertEquals("The renewed tracked dataset must see the committed addition", 1,
						rootDataset.getStatementCount(subject, predicate, added.getObject()));
			}

			try (SailDataset current = source.dataset(IsolationLevels.NONE)) {
				assertEquals(0, current.getStatementCount(subject, predicate, second.getObject()));
				assertEquals(1, current.getStatementCount(subject, predicate, added.getObject()));
			}
		} finally {
			executor.shutdownNow();
			backingStore.close();
		}
	}

	@Test
	public void testStatementCountWaitsForDictionaryPublicationAfterQuadCommit(@TempDir File root) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		StoreProperties properties = new StoreProperties(root);
		ValueStore realValueStore = new ValueStore(new File(root, "values"), properties, config);
		CountDownLatch dictionaryCommitEntered = new CountDownLatch(1);
		CountDownLatch allowDictionaryCommit = new CountDownLatch(1);
		CountDownLatch countReleasedLease = new CountDownLatch(1);
		AtomicBoolean pauseDictionaryCommit = new AtomicBoolean();
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			try (MockedConstruction<ValueStore> valueStoreMocks = mockConstruction(ValueStore.class,
					org.mockito.Mockito.withSettings()
							.defaultAnswer(org.mockito.AdditionalAnswers.delegatesTo(realValueStore)),
					(mock, context) -> doAnswer(invocation -> {
						if (pauseDictionaryCommit.get()) {
							dictionaryCommitEntered.countDown();
							if (!allowDictionaryCommit.await(10, TimeUnit.SECONDS)) {
								throw new IOException("Timed out waiting to publish the test dictionary transaction");
							}
						}
						realValueStore.commit();
						return null;
					}).when(mock).commit());
					LmdbSailStore backingStore = new LmdbSailStore(root, properties, config, false)) {
				assertEquals("The fresh store must use the delegated ValueStore instance", 1,
						valueStoreMocks.constructed().size());
				Resource subject = F.createIRI("urn:count-publication:subject");
				IRI predicate = F.createIRI("urn:count-publication:predicate");
				Value object = F.createLiteral("count-publication-value-".repeat(32));
				Future<?> write;
				try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
					sink.approve(subject, predicate, object, null);
					pauseDictionaryCommit.set(true);
					write = executor.submit(() -> sink.flush());
					assertTrue("Sink flush must reach ValueStore.commit after committing the quad index",
							dictionaryCommitEntered.await(10, TimeUnit.SECONDS));

					Future<Long> count = executor.submit(() -> {
						try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE)) {
							return new CountAdmissionDataset(dataset, countReleasedLease)
									.getStatementCount(subject, predicate, object);
						}
					});
					assertTrue("The count must release its captured leases before dictionary publication resumes",
							countReleasedLease.await(10, TimeUnit.SECONDS));
					allowDictionaryCommit.countDown();
					assertEquals(1L, count.get(10, TimeUnit.SECONDS).longValue());
					write.get(10, TimeUnit.SECONDS);
				} finally {
					allowDictionaryCommit.countDown();
				}
			}
		} finally {
			executor.shutdownNow();
			realValueStore.close();
		}
	}

	private static final class CountAdmissionDataset implements SailDataset {
		private final SailDataset delegate;
		private final CountDownLatch countReleasedLease;

		private CountAdmissionDataset(SailDataset delegate, CountDownLatch countReleasedLease) {
			this.delegate = delegate;
			this.countReleasedLease = countReleasedLease;
		}

		@Override
		public void close() throws SailException {
			delegate.close();
		}

		@Override
		public CloseableIteration<? extends Namespace> getNamespaces() throws SailException {
			return delegate.getNamespaces();
		}

		@Override
		public String getNamespace(String prefix) throws SailException {
			return delegate.getNamespace(prefix);
		}

		@Override
		public CloseableIteration<? extends Resource> getContextIDs() throws SailException {
			return delegate.getContextIDs();
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws SailException {
			return delegate.getStatements(subj, pred, obj, contexts);
		}

		@Override
		public long getStatementCount(Resource subj, IRI pred, Value obj, Resource... contexts) {
			return StatementCountSources.count(this, subj, pred, obj, contexts);
		}

		@Override
		public StatementCountSource prepareStatementCount(StatementCountScope scope) {
			StatementCountSource source = delegate.prepareStatementCount(scope);
			scope.register(this, new StatementCountScope.CountResource() {
				@Override
				public long order() {
					return Long.MAX_VALUE;
				}

				@Override
				public void releaseLease() {
					countReleasedLease.countDown();
				}
			});
			return source;
		}
	}

	@Test
	public void testStatementCountPreservesRdfTermKindsWithInlineLiteralsEnabledAndDisabled(@TempDir File root)
			throws Exception {
		for (boolean inlineLiterals : new boolean[] { false, true }) {
			LmdbStore store = new LmdbStore(new File(root, "inline-" + inlineLiterals),
					new LmdbStoreConfig("spoc,posc").setInlineLiterals(inlineLiterals));
			store.init();
			try {
				LmdbSailStore backingStore = store.getBackingStore();
				IRI predicate = F.createIRI("urn:count-term-kind:predicate");
				BNode blankSubject = F.createBNode("subject");
				BNode blankContext = F.createBNode("context");
				Literal typedLiteral = F.createLiteral("7", XSD.INT);
				Literal languageLiteral = F.createLiteral("hello", "en");
				Literal directionalLiteral = F.createLiteral("שלום", "he", Literal.BaseDirection.RTL);
				Literal longLiteral = F.createLiteral("non-inline-count-value-".repeat(80));
				TripleTerm inner = F.createTripleTerm(F.createIRI("urn:count-term-kind:inner-subject"), RDF.TYPE,
						F.createLiteral("inner-object"));
				TripleTerm nestedObject = F.createTripleTerm(F.createIRI("urn:count-term-kind:nested-subject"),
						predicate,
						inner);
				Resource nestedStatementSubject = F.createIRI("urn:count-term-kind:nested-statement-subject");
				Resource iriContext = F.createIRI("urn:count-term-kind:context");
				List<Statement> statements = List.of(
						F.createStatement(blankSubject, predicate, typedLiteral),
						F.createStatement(F.createIRI("urn:count-term-kind:language"), predicate, languageLiteral,
								iriContext),
						F.createStatement(F.createIRI("urn:count-term-kind:direction"), predicate, directionalLiteral,
								blankContext),
						F.createStatement(nestedStatementSubject, predicate, nestedObject, blankContext),
						F.createStatement(F.createIRI("urn:count-term-kind:long"), predicate, longLiteral));

				try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
					for (Statement statement : statements) {
						sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(),
								statement.getContext());
					}
					sink.flush();
				}

				try (MockedConstruction<LmdbRecordIterator> recordIterators = mockConstruction(
						LmdbRecordIterator.class,
						(mock, context) -> doThrow(
								new AssertionError("Native nested counts must not iterate raw records"))
								.when(mock)
								.next());
						MockedConstruction<LmdbStatementIterator> statementIterators = mockConstruction(
								LmdbStatementIterator.class,
								(mock, context) -> doThrow(
										new AssertionError("Native nested counts must not iterate statements"))
										.when(mock)
										.next());
						SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE)) {
					assertEquals("inline literals: " + inlineLiterals, statements.size(),
							dataset.getStatementCount(null, null, null));
					assertEquals("inline literals: " + inlineLiterals, 1,
							dataset.getStatementCount(blankSubject, predicate, typedLiteral));
					assertEquals("Datatype must participate in exact term matching", 0,
							dataset.getStatementCount(blankSubject, predicate, F.createLiteral("7", XSD.STRING)));
					assertEquals("Language tags are case insensitive", 1,
							dataset.getStatementCount(null, predicate, F.createLiteral("hello", "EN"), iriContext));
					assertEquals(0,
							dataset.getStatementCount(null, predicate, F.createLiteral("hello", "fr"), iriContext));
					assertEquals(1, dataset.getStatementCount(null, predicate,
							F.createLiteral("שלום", "he", Literal.BaseDirection.RTL), blankContext));
					assertEquals(0, dataset.getStatementCount(null, predicate,
							F.createLiteral("שלום", "he", Literal.BaseDirection.LTR), blankContext));
					assertEquals(1,
							dataset.getStatementCount(nestedStatementSubject, predicate, nestedObject, blankContext));
					assertEquals(0, dataset.getStatementCount(nestedStatementSubject, predicate,
							F.createTripleTerm(F.createIRI("urn:count-term-kind:different"), predicate,
									directionalLiteral),
							blankContext));
					assertEquals(1, dataset.getStatementCount(null, predicate, longLiteral));
					assertTrue("Native nested counts must not construct raw record iterators",
							recordIterators.constructed().isEmpty());
					assertTrue("Native nested counts must not construct statement iterators",
							statementIterators.constructed().isEmpty());
				}
			} finally {
				store.shutDown();
			}
		}
	}

	@Test
	public void testStatementCountHandlesRdfEqualNaNPayloadAliasesAcrossRemovalAndNestedReadd(@TempDir File root)
			throws Exception {
		for (boolean floatValue : new boolean[] { true, false }) {
			String family = floatValue ? "float" : "double";
			LmdbStore store = new LmdbStore(new File(root, family),
					new LmdbStoreConfig("spoc,posc").setInlineLiterals(true));
			store.init();
			try {
				LmdbSailStore backingStore = store.getBackingStore();
				ValueStore values = (ValueStore) backingStore.getValueFactory();
				Literal first = floatValue
						? values.createLiteral(Float.intBitsToFloat(0x7fc00001))
						: values.createLiteral(Double.longBitsToDouble(0x7ff8000000000001L));
				Literal second = floatValue
						? values.createLiteral(Float.intBitsToFloat(0x7fc00002))
						: values.createLiteral(Double.longBitsToDouble(0x7ff8000000000002L));
				assertEquals("NaN", first.getLabel());
				assertEquals("Different raw payloads are the same RDF literal", first, second);
				long firstId = values.getId(first, true);
				values.clearCaches();
				long secondId = values.getId(second, true);
				assertNotEquals("Distinct raw NaN payloads must retain distinct inline IDs", firstId, secondId);

				Resource subject = F.createIRI("urn:nan-count:" + family + ":subject");
				IRI predicate = F.createIRI("urn:nan-count:" + family + ":predicate");
				values.clearCaches();
				try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
					sink.approve(subject, predicate, first, null);
					sink.flush();
				}
				values.clearCaches();
				try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
					sink.approve(subject, predicate, second, null);
					sink.flush();
				}

				try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE)) {
					assertEquals(family, 2, dataset.getStatementCount(null, null, null));
					assertEquals(family, 2, dataset.getStatementCount(subject, predicate, first));
					assertEquals(family, 2, dataset.getStatementCount(subject, predicate, second));
					Statement[] held = { F.createStatement(subject, predicate, second) };
					try (StatementCountScope scope = new StatementCountScope(subject, predicate, first,
							new Resource[0])) {
						StatementCountSource nativeSource = dataset.prepareStatementCount(scope);
						StatementCountSource heldSource = StatementCountSources.fromStatements(held, scope);
						assertTrue(scope.freeze());
						assertEquals(family, 2, nativeSource.count(subject, predicate, first, new Resource[0],
								StatementCountSources.contains(heldSource), scope));
						assertEquals(family, 1, heldSource.count(subject, predicate, second, new Resource[0],
								StatementCountSources.contains(nativeSource), scope));
					}
				}

				try (SnapshotSailStore snapshots = new SnapshotSailStore(backingStore, LinkedHashModel::new);
						SailSource removalBranch = snapshots.getExplicitSailSource().fork()) {
					try (SailSink sink = removalBranch.sink(IsolationLevels.SNAPSHOT)) {
						sink.deprecate(F.createStatement(subject, predicate, first));
						sink.flush();
					}
					try (SailDataset removed = removalBranch.dataset(IsolationLevels.SNAPSHOT)) {
						assertEquals("A single logical removal must hide every physical RDF-equal NaN alias: " + family,
								0, removed.getStatementCount(subject, predicate, second));
					}
					try (SailSource readdBranch = removalBranch.fork()) {
						try (SailSink sink = readdBranch.sink(IsolationLevels.SNAPSHOT)) {
							sink.clear();
							sink.approve(subject, predicate, second, null);
							sink.flush();
						}
						try (SailDataset readded = readdBranch.dataset(IsolationLevels.SNAPSHOT)) {
							assertEquals(
									"A nested clear followed by re-add must expose one logical RDF statement: "
											+ family,
									1, readded.getStatementCount(subject, predicate, first));
						}
					}
				}
			} finally {
				store.shutDown();
			}
		}
	}

	@Test
	public void testSnapshotCountAcrossIndependentLmdbDeltaStoresAndNestedBranches(@TempDir File root)
			throws Exception {
		File backingDirectory = new File(root, "backing");
		if (!backingDirectory.isDirectory() && !backingDirectory.mkdirs()) {
			throw new IOException("Could not create snapshot-count backing store directory: " + backingDirectory);
		}
		LmdbSailStore backingStore = new LmdbSailStore(backingDirectory, new StoreProperties(backingDirectory),
				new LmdbStoreConfig("spoc,posc"));
		IRI predicate = F.createIRI("urn:snapshot-count:predicate");
		Resource context = F.createIRI("urn:snapshot-count:context");
		Resource sharedSubject = F.createIRI("urn:snapshot-count:shared");
		Statement shared = F.createStatement(sharedSubject, predicate, F.createLiteral("shared"), context);
		Statement removed = F.createStatement(F.createIRI("urn:snapshot-count:removed"), predicate,
				F.createLiteral("removed"), context);
		Statement retained = F.createStatement(F.createIRI("urn:snapshot-count:retained"), predicate,
				F.createLiteral("retained"), context);
		Statement added = F.createStatement(F.createIRI("urn:snapshot-count:added"), predicate,
				F.createLiteral("added"), context);
		Statement nestedAdded = F.createStatement(F.createIRI("urn:snapshot-count:nested-added"), predicate,
				F.createLiteral("nested-added"), context);
		File deltasDirectory = new File(root, "deltas");
		if (!deltasDirectory.isDirectory() && !deltasDirectory.mkdirs()) {
			throw new IOException("Could not create snapshot-count delta directory: " + deltasDirectory);
		}
		try (LmdbBackedModelFactory models = new LmdbBackedModelFactory(deltasDirectory);
				SnapshotSailStore snapshots = new SnapshotSailStore(backingStore, models);
				SailSource nested = snapshots.getExplicitSailSource().fork()) {
			try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
				for (Statement statement : List.of(shared, removed, retained)) {
					sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(),
							statement.getContext());
				}
				sink.flush();
			}

			try (SailSink sink = snapshots.getExplicitSailSource().sink(IsolationLevels.SNAPSHOT)) {
				sink.approve(shared.getSubject(), shared.getPredicate(), shared.getObject(), shared.getContext());
				sink.approve(added.getSubject(), added.getPredicate(), added.getObject(), added.getContext());
				sink.deprecate(removed);
				sink.flush();
			}
			try (SailDataset dataset = snapshots.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT)) {
				assertEquals(3, dataset.getStatementCount(null, null, null, context));
				assertEquals("An addition already present in the backing store must not be double counted", 1,
						dataset.getStatementCount(shared.getSubject(), predicate, shared.getObject(), context));
				assertEquals(0,
						dataset.getStatementCount(removed.getSubject(), predicate, removed.getObject(), context));
				assertEquals(1, dataset.getStatementCount(added.getSubject(), predicate, added.getObject(), context));
			}
			try (SailDataset dataset = snapshots.getExplicitSailSource().dataset(IsolationLevels.SERIALIZABLE)) {
				assertEquals(3, dataset.getStatementCount(null, null, null, context));
				assertEquals(1, dataset.getStatementCount(added.getSubject(), predicate, added.getObject(), context));
			}

			try (SailSink sink = nested.sink(IsolationLevels.SNAPSHOT)) {
				sink.approve(nestedAdded.getSubject(), nestedAdded.getPredicate(), nestedAdded.getObject(),
						nestedAdded.getContext());
				sink.deprecate(shared);
				sink.flush();
			}
			try (SailDataset dataset = nested.dataset(IsolationLevels.SNAPSHOT)) {
				assertEquals(3, dataset.getStatementCount(null, null, null, context));
				assertEquals(0, dataset.getStatementCount(shared.getSubject(), predicate, shared.getObject(), context));
				assertEquals(0,
						dataset.getStatementCount(removed.getSubject(), predicate, removed.getObject(), context));
				assertEquals(1,
						dataset.getStatementCount(retained.getSubject(), predicate, retained.getObject(), context));
				assertEquals(1, dataset.getStatementCount(added.getSubject(), predicate, added.getObject(), context));
				assertEquals(1, dataset.getStatementCount(nestedAdded.getSubject(), predicate, nestedAdded.getObject(),
						context));
			}
			assertEquals("Each approved/deprecated delta model must own its own LMDB store", 4, models.stores.size());
			assertNotSame(models.stores.get(0).getValueFactory(), models.stores.get(1).getValueFactory());
		}
	}

	private static final class LmdbBackedModelFactory implements ModelFactory, AutoCloseable {
		private final File root;
		private final List<LmdbSailStore> stores = new ArrayList<>();

		private LmdbBackedModelFactory(File root) {
			this.root = root;
		}

		@Override
		public Model createEmptyModel() {
			File directory = new File(root, "model-" + stores.size());
			try {
				if (!directory.isDirectory() && !directory.mkdirs()) {
					throw new IOException("Could not create LMDB model directory: " + directory);
				}
				LmdbSailStore store = new LmdbSailStore(directory, new StoreProperties(directory),
						new LmdbStoreConfig("spoc,posc"));
				stores.add(store);
				return new SailSourceModel(store);
			} catch (IOException e) {
				throw new UncheckedIOException(e);
			}
		}

		@Override
		public void close() throws SailException {
			for (LmdbSailStore store : stores) {
				store.close();
			}
		}
	}

	@Test
	public void testStatementCountAcrossSpocIndexPermutationsAndContextSets(@TempDir File permutationRoot)
			throws Exception {
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		Resource subjectOne = valueFactory.createIRI("urn:index:subject:one");
		Resource subjectTwo = valueFactory.createIRI("urn:index:subject:two");
		IRI predicateOne = valueFactory.createIRI("urn:index:predicate:one");
		IRI predicateTwo = valueFactory.createIRI("urn:index:predicate:two");
		Value objectOne = valueFactory.createLiteral("one");
		Value objectTwo = valueFactory.createLiteral("two");
		Resource contextOne = valueFactory.createIRI("urn:index:context:one");
		Resource contextTwo = valueFactory.createIRI("urn:index:context:two");
		Resource unknownContext = valueFactory.createIRI("urn:index:context:unknown");
		List<Statement> statements = List.of(
				valueFactory.createStatement(subjectOne, predicateOne, objectOne, contextOne),
				valueFactory.createStatement(subjectOne, predicateOne, objectTwo, contextTwo),
				valueFactory.createStatement(subjectTwo, predicateTwo, objectOne, contextOne),
				valueFactory.createStatement(subjectTwo, predicateTwo, objectTwo, contextTwo),
				valueFactory.createStatement(subjectOne, predicateOne, objectOne),
				valueFactory.createStatement(subjectTwo, predicateTwo, objectTwo));

		List<String> indexOrders = new ArrayList<>();
		addIndexPermutations("spoc", "", indexOrders);
		assertEquals("All 24 SPOC single-index permutations must be exercised", 24, indexOrders.size());
		for (String indexOrder : indexOrders) {
			LmdbStore permutationStore = new LmdbStore(new File(permutationRoot, indexOrder),
					new LmdbStoreConfig(indexOrder));
			permutationStore.init();
			try {
				LmdbSailStore backingStore = permutationStore.getBackingStore();
				try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
					for (Statement statement : statements) {
						sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(),
								statement.getContext());
					}
					sink.flush();
				}

				try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE)) {
					assertEquals(indexOrder, 6, dataset.getStatementCount(null, null, null));
					assertEquals(indexOrder, 3, dataset.getStatementCount(subjectOne, null, null));
					assertEquals(indexOrder, 3, dataset.getStatementCount(null, predicateOne, null));
					assertEquals(indexOrder, 3, dataset.getStatementCount(null, null, objectOne));
					assertEquals(indexOrder, 3, dataset.getStatementCount(subjectOne, predicateOne, null));
					assertEquals(indexOrder, 2, dataset.getStatementCount(subjectOne, null, objectOne));
					assertEquals(indexOrder, 2, dataset.getStatementCount(null, predicateOne, objectOne));
					assertEquals(indexOrder, 1,
							dataset.getStatementCount(subjectOne, predicateOne, objectTwo, contextTwo));
					assertEquals(indexOrder, 2, dataset.getStatementCount(null, null, null, contextOne));
					assertEquals(indexOrder, 4, dataset.getStatementCount(null, null, null, contextOne, contextTwo));
					assertEquals(indexOrder, 2,
							dataset.getStatementCount(null, null, null, new Resource[] { null }));
					assertEquals(indexOrder, 1,
							dataset.getStatementCount(subjectOne, predicateOne, objectOne, new Resource[] { null }));
					assertEquals(indexOrder, 2, dataset.getStatementCount(null, null, null, contextOne, contextOne));
					assertEquals(indexOrder, 2,
							dataset.getStatementCount(null, null, null, contextOne, unknownContext));
					assertEquals(indexOrder, 0, dataset.getStatementCount(null, null, null, unknownContext));
					assertEquals(indexOrder, 6,
							dataset.getStatementCount(null, null, null,
									new Resource[] { null, contextOne, contextTwo }));
					assertEquals(indexOrder, 6,
							dataset.getStatementCount(null, null, null,
									new Resource[] { contextTwo, null, unknownContext, contextOne, contextTwo }));
				}
			} finally {
				permutationStore.shutDown();
			}
		}
	}

	private static void addIndexPermutations(String remaining, String prefix, List<String> indexOrders) {
		if (remaining.isEmpty()) {
			indexOrders.add(prefix);
			return;
		}
		for (int i = 0; i < remaining.length(); i++) {
			addIndexPermutations(remaining.substring(0, i) + remaining.substring(i + 1),
					prefix + remaining.charAt(i), indexOrders);
		}
	}

	@Test
	public void testStatementCountTracksInferredStatementsAndPromotion() throws SailException {
		LmdbStore sail = (LmdbStore) ((SailRepository) repo).getSail();
		LmdbSailStore backingStore = sail.getBackingStore();
		Statement inferredStatement = F.createStatement(F.createIRI("urn:inferred-subject"), RDFS.LABEL,
				F.createLiteral("inferred"), CTX_1);

		try (SailSink sink = backingStore.getInferredSailSource().sink(IsolationLevels.NONE)) {
			sink.approve(inferredStatement.getSubject(), inferredStatement.getPredicate(),
					inferredStatement.getObject(),
					inferredStatement.getContext());
			sink.flush();
		}

		try (SailDataset explicit = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE);
				SailDataset inferred = backingStore.getInferredSailSource().dataset(IsolationLevels.NONE)) {
			assertEquals(0, explicit.getStatementCount(inferredStatement.getSubject(), inferredStatement.getPredicate(),
					inferredStatement.getObject(), CTX_1));
			assertEquals(1, inferred.getStatementCount(inferredStatement.getSubject(), inferredStatement.getPredicate(),
					inferredStatement.getObject(), CTX_1));
		}

		try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			sink.approve(inferredStatement.getSubject(), inferredStatement.getPredicate(),
					inferredStatement.getObject(),
					inferredStatement.getContext());
			sink.flush();
		}
		try (SailSink sink = backingStore.getInferredSailSource().sink(IsolationLevels.NONE)) {
			sink.deprecate(inferredStatement);
			sink.flush();
		}

		try (SailDataset explicit = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE);
				SailDataset inferred = backingStore.getInferredSailSource().dataset(IsolationLevels.NONE)) {
			assertEquals(1, explicit.getStatementCount(inferredStatement.getSubject(), inferredStatement.getPredicate(),
					inferredStatement.getObject(), CTX_1));
			assertEquals(0, inferred.getStatementCount(inferredStatement.getSubject(), inferredStatement.getPredicate(),
					inferredStatement.getObject(), CTX_1));
		}
	}

	@Test
	public void testRepositorySizeReflectsTransactionalAddRemoveClearAndRollback() {
		try (RepositoryConnection connection = repo.getConnection()) {
			assertEquals(3, connection.size());
			assertEquals(1, connection.size(CTX_1));

			connection.begin(IsolationLevels.SNAPSHOT);
			connection.add(F.createIRI("urn:transactional-subject"), RDFS.LABEL, F.createLiteral("added"), CTX_1);
			assertEquals(4, connection.size());
			assertEquals(2, connection.size(CTX_1));

			connection.remove(S1.getSubject(), S1.getPredicate(), S1.getObject(), CTX_1);
			assertEquals(3, connection.size());
			assertEquals(1, connection.size(CTX_1));

			connection.clear(CTX_2);
			assertEquals(2, connection.size());
			connection.commit();
			assertEquals(2, connection.size());

			connection.begin(IsolationLevels.SNAPSHOT);
			connection.add(F.createIRI("urn:rolled-back-subject"), RDFS.LABEL, F.createLiteral("rolled back"), CTX_2);
			assertEquals(3, connection.size());
			connection.rollback();
			assertEquals(2, connection.size());
		}
	}

	@Test
	public void testRecordIteratorContinuesAfterDeletedCurrentRecordAcrossRenewal() throws Exception {
		LmdbStore sail = (LmdbStore) ((SailRepository) repo).getSail();
		LmdbSailStore backingStore = sail.getBackingStore();
		List<Statement> statementsBeforeDeletion = new ArrayList<>();

		try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE);
				CloseableIteration<? extends Statement> statements = dataset.getStatements(null, null, null)) {
			while (statements.hasNext()) {
				statementsBeforeDeletion.add(statements.next());
			}
		}
		assertEquals(3, statementsBeforeDeletion.size());

		Statement deleted = statementsBeforeDeletion.getFirst();
		Statement immediateSuccessor = statementsBeforeDeletion.get(1);
		try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE);
				CloseableIteration<? extends Statement> statements = dataset.getStatements(null, null, null)) {
			assertEquals(deleted, statements.next());

			try (RepositoryConnection connection = repo.getConnection()) {
				connection.remove(deleted);
			}

			assertEquals(immediateSuccessor, statements.next());
		}
	}

